import json
import sys
from pathlib import Path


# Minimum accuracy required for the model
MINIMUM_ACCURACY = 0.85


# Metrics are generated by Experiment-2
METRICS_PATH = (
    Path(__file__).resolve().parent.parent
    / "Experiment-2"
    / "metrics.json"
)


print("Reading model evaluation metrics...")


if not METRICS_PATH.exists():
    print("ERROR: metrics.json was not found.")
    print(
        "Make sure Experiment-2 training completed "
        "before running the quality gate."
    )
    sys.exit(1)


with open(
    METRICS_PATH,
    "r",
    encoding="utf-8"
) as file:

    metrics = json.load(file)


accuracy = metrics["accuracy"]


print(
    "Model Accuracy :",
    round(accuracy, 4)
)

print(
    "Required Accuracy:",
    MINIMUM_ACCURACY
)


if accuracy < MINIMUM_ACCURACY:

    print("QUALITY GATE FAILED")

    print(
        "Model performance is below "
        "the required threshold."
    )

    sys.exit(1)


print("QUALITY GATE PASSED")

print(
    "Model performance satisfies "
    "the required threshold."
)

sys.exit(0)
